-- Phase 6a: real branches, TKM (CTDMS) code mapping, full dealer price lists, EW matrix,
-- accessory/VAS categorisation, and the columns needed to hold bookings imported from the CTDMS
-- PO Order Listing. Data itself is loaded by 20261024000002_master_data_seed.sql (generated by
-- scripts/seed/build_master_seed.py from the dealership's source files).

-- ===== Branches =====
alter table outlets add column ctdms_dealer_code text;
create unique index uq_outlets_ctdms_dealer_code on outlets(ctdms_dealer_code) where ctdms_dealer_code is not null;

-- The Phase 0 seed's Jaipur outlet is the real Jaipur branch; Jodhpur was a placeholder.
update outlets set name = 'Rajesh Toyota - Jaipur', ctdms_dealer_code = 'JP05A'
where id = '00000000-0000-0000-0002-000000000001';
update outlets set is_active = false
where id = '00000000-0000-0000-0002-000000000002';

insert into outlets (id, name, dealer_code, ctdms_dealer_code, city, state, address) values
  ('00000000-0000-0000-0002-000000000003', 'Rajesh Toyota - Dausa', 'DN01A', 'DN01A', 'Dausa', 'Rajasthan', 'Dausa'),
  ('00000000-0000-0000-0002-000000000004', 'Rajesh Toyota - Kotputli', 'VK01A', 'VK01A', 'Kotputli', 'Rajasthan', 'Kotputli');

-- ===== Employees: CTDMS name, used to match Sales Officer / Team Leader columns in CTDMS reports =====
alter table employees add column ctdms_name text;
create index idx_employees_ctdms_name on employees(upper(ctdms_name));

-- ===== Catalog: TKM codes =====
alter table models add column tkm_model_code text;
create unique index uq_models_tkm_model_code on models(tkm_model_code) where tkm_model_code is not null;

-- tkm_suffix_code is the full 5-character CTDMS code (model prefix + suffix), e.g. D22U4, FRN1L.
alter table variants add column tkm_suffix_code text;
alter table variants add column old_suffix_code text;
create unique index uq_variants_tkm_suffix_code on variants(tkm_suffix_code) where tkm_suffix_code is not null;

-- paint_category links a colour to the price-list row that applies to it (Pearl White and dual-tone
-- paints carry their own ex-showroom price in TKM lists).
alter table colors add column tkm_color_code text;
alter table colors add column paint_category text not null default 'standard';
alter table colors add constraint colors_paint_category_check
  check (paint_category in ('standard', 'pearl_white', 'dual_tone'));
create unique index uq_colors_tkm_color_code on colors(tkm_color_code) where tkm_color_code is not null;

insert into fuel_types (id, name) values
  ('00000000-0000-0000-0004-000000000004', 'CNG'),
  ('00000000-0000-0000-0004-000000000005', 'EV');
insert into transmissions (id, name) values
  ('00000000-0000-0000-0005-000000000004', 'AMT');

-- ===== Price list: the full dealer list =====
-- One row per variant x list type x paint category (or x specific colour, for the legacy per-colour
-- rows the CSV importer writes) x effective date. Amounts are exactly what the printed list shows.
alter table price_list alter column color_id drop not null;
alter table price_list
  add column list_type text not null default 'private',
  add column paint_category text not null default 'standard',
  add column tcs_amount numeric,
  add column road_tax_registration numeric,
  -- Keyed by option: advance | premium | premium_3plus3 | luxury (whichever the list prints).
  add column insurance_options jsonb not null default '{}'::jsonb,
  add column fastag_amount numeric,
  add column ew_5th_year_amount numeric,
  add column tgloss_package_amount numeric,
  add column tga_combo_amount numeric,
  add column essential_kit_amount numeric,
  add column smile_package_amount numeric,
  add column on_road_listed numeric,
  add column source_file text,
  add constraint price_list_list_type_check check (list_type in ('private', 'commercial', 'csd')),
  add constraint price_list_paint_category_check check (paint_category in ('standard', 'pearl_white', 'dual_tone')),
  add constraint price_list_color_or_paint check (color_id is not null or paint_category is not null);
drop index if exists idx_price_list_lookup;
create index idx_price_list_lookup on price_list(variant_id, state, list_type, effective_from, effective_to);

-- ===== Extended warranty (T-Secure) customer price matrix =====
create table ew_prices (
  id uuid primary key default gen_random_uuid(),
  model_group text not null,
  model_id uuid references models(id),
  min_age_months int not null,
  max_age_months int not null,
  product text not null,
  km_limit int,
  price numeric not null,
  effective_from date not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (max_age_months >= min_age_months),
  check (product in ('true_warranty_4th_year', 'true_warranty_5th_year', 'driveline_5th_year', 'unlimited_5th_year'))
);
create index idx_ew_prices_model on ew_prices(model_id, min_age_months);
create trigger trg_ew_prices_updated_at before update on ew_prices for each row execute function set_updated_at();

alter table ew_prices enable row level security;
create policy ew_prices_select on ew_prices for select to authenticated using (true);
create policy ew_prices_write on ew_prices for all to authenticated
  using (is_master_data_admin()) with check (is_master_data_admin());

-- ===== Accessories / VAS =====
alter table accessories
  add column category text,
  add column is_tga boolean not null default true,
  add column sort_order int,
  add column effective_from date,
  add column is_active boolean not null default true;
alter table vas_products
  add column model_id uuid references models(id),
  add column category text,
  add column is_active boolean not null default true;
create index idx_vas_products_model_id on vas_products(model_id);

-- Placeholder Phase 0 catalog rows are superseded by the real catalog in the seed migration.
update variants set is_active = false where id in (
  '00000000-0000-0000-0007-000000000001', '00000000-0000-0000-0007-000000000002', '00000000-0000-0000-0007-000000000003');
update accessories set is_active = false where part_no like 'ACC-%';
update vas_products set is_active = false where model_id is null;

-- ===== Quotes / bookings: price-list selections =====
alter table quotes
  add column price_list_type text not null default 'private',
  add column insurance_option text,
  add column include_extended_warranty boolean not null default false;
alter table bookings
  add column price_list_type text not null default 'private',
  add column insurance_option text,
  add column include_extended_warranty boolean not null default false;

-- ===== Bookings imported from the CTDMS PO Order Listing =====
-- Imported orders may reference suffix/colour codes not yet in the catalog, and carry no RTO
-- category or SC login, so those become nullable for imported rows only.
alter table bookings
  add column ctdms_order_id text,
  add column ctdms_order_date date,
  add column ctdms_order_status text,
  add column ctdms_customer_code text,
  add column ctdms_icrop_enquiry_no text,
  add column ctdms_suffix_code text,
  add column ctdms_color_code text,
  add column ctdms_sales_officer text,
  add column ctdms_team_leader text,
  add column customer_name text,
  add column organization_name text,
  add column institutional_group_type text,
  add column received_amount numeric,
  add column imported_from_ctdms boolean not null default false;
alter table bookings
  alter column variant_id drop not null,
  alter column color_id drop not null,
  alter column rto_category_id drop not null,
  alter column employee_id drop not null;
alter table bookings add constraint bookings_required_unless_imported check (
  imported_from_ctdms or (variant_id is not null and color_id is not null and rto_category_id is not null and employee_id is not null)
);
-- CTDMS order numbers run per dealer code (Jaipur and Dausa both have ORD261000021).
create unique index uq_bookings_outlet_ctdms_order_no on bookings(outlet_id, ctdms_order_booking_no) where ctdms_order_booking_no is not null;
